const incoming = $json ?? {};
const update = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const isEdit = Boolean(update.edited_message || update.edited_channel_post);
const message = update.channel_post || update.edited_channel_post || update.message || update.edited_message || null;
if (!message) {
  return [{ json: { ...incoming, is_status_update: true, event: 'telegram.update', raw_body: update, raw_body_string: JSON.stringify(update), raw_headers: incoming.headers || {} } }];
}
const chat = message.chat || {};
const sender = message.from || message.sender_chat || {};
// Bot-originated messages and edits never re-enter the agent loop: bot replies
// would self-trigger, and each edit re-fires a full agent turn (duplicate replies).
if (sender.is_bot === true || isEdit) {
  return [{ json: { ...incoming, is_status_update: true, event: isEdit ? 'message.edited_ignored' : 'bot_message_ignored', raw_body: update, raw_body_string: JSON.stringify(update), raw_headers: incoming.headers || {} } }];
}
const messageText = message.text ?? message.caption ?? '';
const chatId = chat.id ?? null;
const senderId = sender.id ?? chatId;
const messageId = message.message_id ?? null;
const sourceEventId = update.update_id ?? messageId;
const idempotencyKey = chatId !== null && sourceEventId !== null ? `telegram:${chatId}:${sourceEventId}` : null;
const receivedAt = message.date ? new Date(Number(message.date) * 1000).toISOString() : new Date().toISOString();
const messageType = message.photo || message.video || message.document || message.audio ? 'media' : 'text';
return [{ json: {
  ...incoming,
  is_status_update: false,
  event: 'message.received',
  raw_body: update,
  raw_body_string: JSON.stringify(update),
  raw_headers: incoming.headers || {},
  channel_type: 'telegram',
  channel_id: chatId,
  channel_username: chat.username ? `@${chat.username}` : null,
  telegram_chat_id: chatId,
  telegram_message_id: messageId,
  channel_patient_id: senderId,
  patient_name: null,
  message_text: messageText,
  text: messageText,
  message_type: messageType,
  message_id: messageId,
  source_event_id: sourceEventId,
  idempotency_key: idempotencyKey,
  received_at: receivedAt,
  conversation_id: chatId,
  attachments: [],
  data: { from: senderId, text: messageText, channel_id: chatId, message_id: messageId, message_type: messageType }
} }];

const message = $('Parse Telegram Message').item.json;
const clinicLookup = $json || {};
return [{ json: {
  ...message,
  clinic_id: clinicLookup.clinic_id || null,
  channel_id: clinicLookup.channel_id || null,
  channel_type: 'telegram',
} }];

const original = $('Merge Clinic With Message').item.json;
const patientResult = $json || {};
let patientId = null;
if (Array.isArray(patientResult.data) && patientResult.data.length > 0) patientId = patientResult.data[0].patient_id;
else if (patientResult.patient_id) patientId = patientResult.patient_id;
else if (Array.isArray(patientResult) && patientResult[0]?.patient_id) patientId = patientResult[0].patient_id;
if (!patientId) throw new Error('Failed to get patient_id from Supabase RPC response');
return [{ json: { ...original, patient_id: patientId } }];

const original = $('Merge Patient Data').item.json;
const convResult = $input.item.json || {};
const rpcRow = convResult?.get_or_create_channel_conversation ?? convResult?.result?.get_or_create_channel_conversation ?? null;
let conversationId = null;
let channelId = null;
if (rpcRow && typeof rpcRow === 'object' && !Array.isArray(rpcRow)) {
  conversationId = rpcRow.conversation_id ?? null;
  channelId = rpcRow.channel_id ?? null;
} else if (convResult.conversation_id) {
  conversationId = convResult.conversation_id;
  channelId = convResult.channel_id ?? null;
} else if (convResult.result?.conversation_id) {
  conversationId = convResult.result.conversation_id;
  channelId = convResult.result.channel_id ?? null;
} else if (Array.isArray(convResult.data) && convResult.data.length) {
  const row = convResult.data[0] || {};
  const nested = row.get_or_create_channel_conversation ?? row.result ?? row;
  conversationId = nested.conversation_id ?? null;
  channelId = nested.channel_id ?? null;
}
if (!conversationId) throw new Error('Failed to get conversation_id from Supabase RPC response');
return [{ json: { ...original, conversation_id: conversationId, channel_id: channelId || original.channel_id || null } }];

const data = $input.item.json || {};
let replyText = data.reply_text || data.final_reply || data.canonical_reply || data.response || data.message || data.answer || data.body || data.output || data.result || null;
if (replyText && typeof replyText === 'object') replyText = replyText.text || replyText.content || JSON.stringify(replyText);
if (!replyText || String(replyText).trim() === '') replyText = 'عذراً، حصلت مشكلة في معالجة طلبك. حاول مرة أخرى.';
replyText = String(replyText).slice(0, 4000);
let original = {};
try { original = $('Parse Telegram Message').item.json || {}; } catch (_) {}
const chatId = data.telegram_chat_id ?? data.channel_patient_id ?? data.chat_id ?? original.telegram_chat_id ?? original.channel_patient_id ?? original.channel_id ?? null;
if (chatId === null || chatId === undefined || String(chatId).trim() === '') throw new Error('Missing Telegram chat ID for reply');
return [{ json: { ...original, ...data, telegram_chat_id: chatId, telegram_reply: replyText } }];

const src = $('Merge Conversation Data').item.json || {};
const core_payload = {
  clinic_id: src.clinic_id || null,
  channel_type: 'telegram',
  channel_id: src.channel_id || null,
  patient_id: src.patient_id || null,
  conversation_id: src.conversation_id || null,
  message_text: src.message_text || '',
  message_id: src.message_id || null,
  source_event_id: src.source_event_id || src.idempotency_key || null,
  metadata: {
    telegram_chat_id: src.telegram_chat_id || null,
    message_type: src.message_type || 'text'
  }
};
return [{ json: { ...src, core_payload } }];

